#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    string t;
    cin >> t;

    size_t i = 0;
    for (char ch : t) {
        if (i < s.size() && ch == s[i]) i++;
    }
    cout << (i == s.size() ? "yes" : "no") << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String t = sc.next();

        int i = 0;
        for (int k = 0; k < t.length(); k++) {
            if (i < s.length() && t.charAt(k) == s.charAt(i)) i++;
        }
        System.out.println(i == s.length() ? "yes" : "no");
    }
}
